if(data.video_path&&typeof window.updateMonitorCombinedVideo==='function'){window.updateMonitorCombinedVideo(data.video_path,{duration:data.duration,size:data.video_size,resolution:data.resolution||data.video_resolution,fps:data.fps||data.video_fps,status:data.status});}
if(progress%10===0||data.status!==(window.lastStatus||'')){console.log('[Progress] Polling update - Progress:',progress+'%','Status:',data.status,'Clips:',data.clips?.length||0,'Editable MP4:',data.editable_mp4_path?'Yes':'No');window.lastStatus=data.status;}
