for(let i=0;i<Math.min(matrixRainDrops.length,columns);i++){const text=chars[Math.floor(Math.random()*chars.length)];const x=i*fontSize;const y=matrixRainDrops[i]*fontSize;const opacity=Math.min(1,Math.max(0.2,(matrixRainCanvas.height-y)/fontSize/10));const intensity=Math.min(255,50+(opacity*205));matrixRainCtx.fillStyle=`rgba(${rgb.r},${rgb.g},${rgb.b},${opacity})`;matrixRainCtx.fillText(text,x,y);if(y>matrixRainCanvas.height&&Math.random()>0.975){matrixRainDrops[i]=0;}else{matrixRainDrops[i]++;}}
