function createTeleportParticles(container){for(let i=0;i<12;i++){const particle=document.createElement('div');particle.style.position='absolute';particle.style.width='4px';particle.style.height='4px';particle.style.background=`rgba(${Math.random()*100+150},${200+Math.random()*55},255,0.8)`;particle.style.borderRadius='50%';particle.style.left='50%';particle.style.top='50%';particle.style.transform=`translate(-50%,-50%)rotate(${i*30}deg)translateY(-35px)`;particle.style.animation=`teleportParticle 2s ease-in-out infinite`;particle.style.animationDelay=`${i*0.15}s`;container.appendChild(particle);}}
function triggerTeleportEffect(){const commercial=document.getElementById('masternoder2-commercial');if(!commercial)return;commercial.style.transform='translateY(-50%) scale(1.1)';commercial.style.filter='brightness(1.5)';setTimeout(function(){commercial.style.transform='translateY(-50%) scale(1)';commercial.style.filter='brightness(1)';},300);}
function createThemeParticles(theme){const particlesContainer=document.getElementById('theme-particles');if(!particlesContainer)return;particlesContainer.innerHTML='';const particleCount=18;const themeColor=hexToRgb(theme.colors.primary);for(let i=0;i<particleCount;i++){const particle=document.createElement('div');particle.className='theme-particle';const size=Math.random()*40+20;particle.style.width=size+'px';particle.style.height=size+'px';particle.style.left=Math.random()*100+'%';particle.style.top=Math.random()*100+'%';particle.style.background=`radial-gradient(circle,rgba(${themeColor.r},${themeColor.g},${themeColor.b},0.4)0%,rgba(${themeColor.r},${themeColor.g},${themeColor.b},0.1)100%)`;particle.style.boxShadow=`0 0 ${size}px rgba(${themeColor.r},${themeColor.g},${themeColor.b},0.5)`;particle.style.animationDelay=Math.random()*20+'s';particle.style.animationDuration=(Math.random()*10+15)+'s';particle.addEventListener('click',function(){const quotes=theme.quotes||[];if(quotes.length>0){const randomQuote=quotes[Math.floor(Math.random()*quotes.length)];showToast(randomQuote,'success');particle.style.transform='scale(3)';particle.style.opacity='1';setTimeout(()=>{particle.style.transform='';particle.style.opacity='';},500);}});particlesContainer.appendChild(particle);}}
