function hexToRgb(hex){const result=/^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);return result?{r:parseInt(result[1],16),g:parseInt(result[2],16),b:parseInt(result[3],16)}:{r:0,g:255,b:0};}
function getThemeContent(type){const theme=themes[currentTheme];if(!theme)return[];switch(type){case'quotes':return theme.quotes||[];case'keywords':return theme.keywords||[];default:return[];}}
